using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class AdvertisementImageConfiguration:IEntityTypeConfiguration<AdvertisementImage>{ public void Configure(EntityTypeBuilder<AdvertisementImage>b){ b.HasKey(x=>x.AdvertisementImageID); b.Property(x=>x.ImageName).HasMaxLength(260).IsRequired(); b.Property(x=>x.ImagePath).HasMaxLength(500).IsRequired(); b.Property(x=>x.ThumbnailPath).HasMaxLength(500).IsRequired(); b.Property(x=>x.Title).HasMaxLength(200); b.Property(x=>x.AltText).HasMaxLength(300); b.HasIndex(x=>new{x.AdvertisementID,x.DisplayOrder}); b.HasOne(x=>x.Advertisement).WithMany(x=>x.Images).HasForeignKey(x=>x.AdvertisementID).OnDelete(DeleteBehavior.Cascade); }}